import{_ as o,o as t,c as a,ag as r}from"./chunks/framework.VvOSaRrC.js";const g=JSON.parse('{"title":"Chat Relay 멀티디바이스 (테이블 + 브라우저 기기 선택기)","description":"","frontmatter":{},"headers":[],"relativePath":"specs/2026-07-06-chat-relay-multidevice-plan.md","filePath":"specs/2026-07-06-chat-relay-multidevice-plan.md"}'),c={name:"specs/2026-07-06-chat-relay-multidevice-plan.md"};function l(d,e,i,n,s,u){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="chat-relay-멀티디바이스-테이블-브라우저-기기-선택기" tabindex="-1">Chat Relay 멀티디바이스 (테이블 + 브라우저 기기 선택기) <a class="header-anchor" href="#chat-relay-멀티디바이스-테이블-브라우저-기기-선택기" aria-label="Permalink to &quot;Chat Relay 멀티디바이스 (테이블 + 브라우저 기기 선택기)&quot;">​</a></h1><p>작성일: 2026-07-06 · 상태: <strong>구현 완료</strong> (relay·client·frontend, 미배포)</p><h2 id="배경-문제" tabindex="-1">배경 / 문제 <a class="header-anchor" href="#배경-문제" aria-label="Permalink to &quot;배경 / 문제&quot;">​</a></h2><p>현재 relay는 <strong>user당 agent 1개</strong>만 지원한다(<code>agents map[string]Sender</code>). 같은 계정으로 두 기기(맥북·윈도우)가 <code>kroot chat start</code> 하면 <code>r.agents[user] = s</code>로 나중 연결이 이전 연결을 조용히 덮고, 진 기기는 ws가 열려 있어도(“연결됨” 표시) 브라우저 요청을 못 받는 <strong>조용한 먹통</strong>이 된다. auto-reconnect까지 겹치면 슬롯 다툼이 반복된다.</p><p>참고: <code>/Users/jikime/Dev/Private/cli-relay</code>는 아직 동일한 single-agent 구조지만, 발급 JWT가 <code>{sub, deviceId}</code>를 담고 클라이언트 credential이 <code>deviceId</code>를 저장한다 — 멀티디바이스의 재료만 준비된 상태.</p><h2 id="목표" tabindex="-1">목표 <a class="header-anchor" href="#목표" aria-label="Permalink to &quot;목표&quot;">​</a></h2><p>같은 계정의 여러 기기를 <strong>동시 연결</strong>로 유지하고, relay가 <strong>기기 테이블</strong>로 관리하며, 브라우저(웹 채팅)가 <strong>기기 목록을 보고 대상 기기를 골라</strong> 프롬프트를 그 기기에서 실행한다.</p><h2 id="프로토콜-변경" tabindex="-1">프로토콜 변경 <a class="header-anchor" href="#프로토콜-변경" aria-label="Permalink to &quot;프로토콜 변경&quot;">​</a></h2><h3 id="_1-agent-레그-—-기기-식별자-전달" tabindex="-1">1) agent 레그 — 기기 식별자 전달 <a class="header-anchor" href="#_1-agent-레그-—-기기-식별자-전달" aria-label="Permalink to &quot;1) agent 레그 — 기기 식별자 전달&quot;">​</a></h3><ul><li>연결 URL에 쿼리 추가: <code>/ws/agent?device=&lt;deviceID&gt;&amp;label=&lt;hostname&gt;</code> (Bearer PAT는 그대로 userID 해석).</li><li><code>device</code> 없으면(구버전) relay가 연결당 유니크 ID를 부여하고 label을 “기기(구버전)”로 → 하위호환.</li></ul><h3 id="_2-relay-→-browser-—-기기-로스터-푸시" tabindex="-1">2) relay → browser — 기기 로스터 푸시 <a class="header-anchor" href="#_2-relay-→-browser-—-기기-로스터-푸시" aria-label="Permalink to &quot;2) relay → browser — 기기 로스터 푸시&quot;">​</a></h3><ul><li>신규 메시지: <code>{&quot;type&quot;:&quot;agent:devices&quot;,&quot;devices&quot;:[{&quot;id&quot;,&quot;label&quot;,&quot;connectedAt&quot;}]}</code></li><li>기기 연결/해제 시 해당 user의 모든 browser로 푸시. browser 접속 즉시 현재 로스터 1회 전송.</li><li>기존 <code>{&quot;type&quot;:&quot;agent:status&quot;,&quot;connected&quot;:bool}</code>는 <code>connected = len(devices)&gt;0</code>으로 <strong>유지</strong>(하위호환).</li></ul><h3 id="_3-browser-→-relay-—-대상-기기-지정" tabindex="-1">3) browser → relay — 대상 기기 지정 <a class="header-anchor" href="#_3-browser-→-relay-—-대상-기기-지정" aria-label="Permalink to &quot;3) browser → relay — 대상 기기 지정&quot;">​</a></h3><ul><li>프롬프트 JSON에 <code>targetDeviceId</code> 필드 추가.</li><li>relay 라우팅: <ul><li><code>targetDeviceId</code> 있고 존재 → 그 기기로 전달.</li><li>없음 + 기기 1개 → 그 기기(하위호환). 없음 + 여러 개 → <strong>가장 최근 연결 기기</strong>로 전달(UI 기본선택과 일치).</li><li><code>targetDeviceId</code> 지정됐으나 오프라인 → <code>{&quot;type&quot;:&quot;agent:unavailable&quot;,&quot;reason&quot;:&quot;device-offline&quot;,&quot;deviceId&quot;:…}</code>.</li></ul></li><li>전달은 <strong>원본 바이트 그대로</strong>(executor는 미지 필드 무시). relay는 라우팅 위해 JSON에서 <code>targetDeviceId</code>만 peek.</li></ul><h2 id="컴포넌트별-변경" tabindex="-1">컴포넌트별 변경 <a class="header-anchor" href="#컴포넌트별-변경" aria-label="Permalink to &quot;컴포넌트별 변경&quot;">​</a></h2><h3 id="a-kroot-server-relay-—-internal-relay" tabindex="-1">A. kroot-server (relay) — <code>internal/relay/</code> <a class="header-anchor" href="#a-kroot-server-relay-—-internal-relay" aria-label="Permalink to &quot;A. kroot-server (relay) — `internal/relay/`&quot;">​</a></h3><ul><li><code>registry.go</code>: <code>agents map[string]map[string]agentEntry</code> (user→deviceID→{sender,label,connectedAt}). <ul><li><code>RegisterAgent(user, deviceID, label, sender) unregister</code> — 같은 deviceID 재등록은 그 기기 갱신.</li><li><code>DevicesFor(user) []DeviceInfo</code>, <code>AgentFor(user, deviceID) (Sender,bool)</code>, <code>MostRecentAgent(user)</code>.</li></ul></li><li><code>server.go</code>: <ul><li><code>handleAgent</code>: 쿼리에서 device/label 파싱 → RegisterAgent. connect/disconnect 시 <code>notifyDevices(user)</code>.</li><li><code>handleBrowser</code>: 접속 시 로스터 전송. 수신 메시지에서 <code>targetDeviceId</code> peek → 라우팅.</li><li><code>agent:status</code>는 로스터 유무로 계속 전송(하위호환).</li></ul></li><li>테스트: registry 다중기기 등록/해제/최근선택, server 라우팅(대상 지정/미지정/오프라인).</li></ul><h3 id="b-kroot-adk-client-—-internal-krootauth-internal-chatagent-cmd-chatcmd" tabindex="-1">B. kroot-adk (client) — <code>internal/krootauth</code>, <code>internal/chatagent</code>, <code>cmd/chatcmd</code> <a class="header-anchor" href="#b-kroot-adk-client-—-internal-krootauth-internal-chatagent-cmd-chatcmd" aria-label="Permalink to &quot;B. kroot-adk (client) — `internal/krootauth`, `internal/chatagent`, `cmd/chatcmd`&quot;">​</a></h3><ul><li><code>credential.go</code>: <code>DeviceID string json:&quot;deviceId,omitempty&quot;</code> 추가 + <code>EnsureDeviceID()</code>(최초 1회 uuid 생성·저장).</li><li><code>chatagent/agent.go</code>: relayURL에 <code>?device=&amp;label=</code> 부착(기존 쿼리 보존, url.Parse 사용). <code>Run</code> 시그니처에 deviceID·label 추가 또는 start.go에서 URL 구성.</li><li><code>cmd/chatcmd/start.go</code>: <code>EnsureDeviceID()</code> 호출, <code>os.Hostname()</code>을 label로 전달.</li></ul><h3 id="c-kroot-main-site-frontend-—-구현됨" tabindex="-1">C. kroot-main-site (frontend) — 구현됨 <a class="header-anchor" href="#c-kroot-main-site-frontend-—-구현됨" aria-label="Permalink to &quot;C. kroot-main-site (frontend) — 구현됨&quot;">​</a></h3><ul><li><code>src/shared/contexts/WebSocketContext.tsx</code>: <ul><li><code>RelayDevice</code> 타입 export. <code>onmessage</code>에 <code>agent:devices</code> 처리 → <code>devices[]</code> 상태, <code>selectedDeviceId</code>(유효하면 유지, 아니면 <strong>최근=마지막</strong> 기기). 소켓 close 시 로스터 초기화. 컨텍스트에 <code>devices, selectedDeviceId, setSelectedDeviceId</code> 노출.</li><li><strong>중앙 주입(개선)</strong>: 개별 송신부를 고치는 대신 <code>sendMessage</code>에서 <code>targetDeviceId</code>를 모든 메시지에 자동 첨부한다. chat뿐 아니라 <code>permission_response</code>·<code>abort</code>·<code>skills_list</code>도 같은 기기로 라우팅돼야 하는데, relay가 browser→agent 전 메시지를 target으로 라우팅하므로 한 곳에서 주입하는 게 정확하고 안전. (선택값은 <code>selectedDeviceIdRef</code>로 stale-closure 회피.)</li></ul></li><li>기기 드롭다운 UI: <code>features/shell/ui/navigation/status-bar.tsx</code> — 채팅 활성 + 기기≥2면 <code>&lt;select&gt;</code>, 1개면 라벨.</li><li><code>stores/agents/chat-link-store.ts</code>: 트리 밖 StatusBar용으로 <code>devices/selectedDeviceId/selectDevice</code> 추가, provider가 publish + setSelector 주입.</li><li>ticket(<code>relay-ticket</code>)은 user 단위라 <strong>변경 없음</strong>.</li></ul><h2 id="하위호환-롤아웃" tabindex="-1">하위호환 / 롤아웃 <a class="header-anchor" href="#하위호환-롤아웃" aria-label="Permalink to &quot;하위호환 / 롤아웃&quot;">​</a></h2><ul><li>구버전 클라이언트(device 미전송) → “기기(구버전)” 단일 기기로 정상 동작.</li><li>구버전 프론트(targetDeviceId 미전송) → 기기 1개면 그대로, 여러 개면 최근 기기로 라우팅.</li><li>릴레이 먼저 배포 → 프론트 → 클라이언트 순서 무관(각 단계 하위호환).</li></ul><h2 id="미결-후순위" tabindex="-1">미결/후순위 <a class="header-anchor" href="#미결-후순위" aria-label="Permalink to &quot;미결/후순위&quot;">​</a></h2><ul><li>agent→browser 이벤트에 <code>sourceDeviceId</code> 태깅(멀티탭 교차 스트림 필터) — v1은 기존처럼 전체 팬아웃.</li><li>기기 이름 사용자 지정(현재 hostname 라벨).</li></ul>',25)])])}const v=o(c,[["render",l]]);export{g as __pageData,v as default};
